// neon.js — NÉON, a minimalist brick breaker (zero dependencies).
//
// This file INTENTIONALLY mixes game logic and rendering in a few places
// (see ISSUES.md #2): brick collision detection currently lives inside the
// draw loop `frame()`. This is deliberate debt, ripe for a refactor.
//
// The module runs nothing on import: only `boot()` touches the DOM. Pure
// logic can therefore be imported from the tests (`node --test`) without a
// browser.

edits.newText:
const STORAGE_KEY = 'neon.best';

// Physics resolution constants.
//
// A physics step is split into substeps of at most SUBSTEP_DIST pixels, so no
// single move can jump over an obstacle (tunneling): a brick is
// BRICK_H + 2*BALL_R = 34px deep and the paddle PADDLE_H + 2*BALL_R = 26px,
// so 20px is safe at every level and every frame rate.
const SUBSTEP_DIST = 20;

// Minimum horizontal velocity (as a fraction of the level speed) after a
// paddle rebound: a dead-center hit would otherwise leave vx = 0 and the ball
// would loop vertically forever.
const PADDLE_MIN_VX_FACTOR = 0.3;

// --- Physics (movement + wall/paddle/brick bounces) ------------------------

// Returns the face of `brick` the ball hit: 'top', 'bottom', 'left', 'right',
// or 'corner' when the entry is ambiguous and BOTH axes must flip.
// `prevX`/`prevY` is the ball centre at the START of the current substep: the
// face is the side the ball was on before it entered the brick. Only when the
// ball was already overlapping before the substep (recovery) do we fall back
// on the dominant velocity axis.
function hitFace(prevX, prevY, ball, brick) {
  const top = prevY - ball.r;
  const bottom = prevY + ball.r;
  const left = prevX - ball.r;
  const right = prevX + ball.r;
  const fromAbove = bottom <= brick.y; // was above, moving down
  const fromBelow = top >= brick.y + brick.h; // was below, moving up
  const fromLeft = right <= brick.x; // was left, moving right
  const fromRight = left >= brick.x + brick.w; // was right, moving left
  const outside = fromAbove + fromBelow + fromLeft + fromRight;
  if (outside >= 2) {
    // Corner entry: the face is the axis of the smallest penetration; equal
    // penetrations mean we are exactly on a corner, and both axes flip.
    const penX = Math.min(ball.x + ball.r, brick.x + brick.w) - Math.max(ball.x - ball.r, brick.x);
    const penY = Math.min(ball.y + ball.r, brick.y + brick.h) - Math.max(ball.y - ball.r, brick.y);
    if (penX === penY) return 'corner';
    return penX < penY ? (fromLeft ? 'left' : 'right') : (fromAbove ? 'top' : 'bottom');
  }
  if (fromAbove) return 'top';
  if (fromBelow) return 'bottom';
  if (fromLeft) return 'left';
  if (fromRight) return 'right';
  // Recovery: already overlapping before the move; resolve along the dominant
  // velocity axis, i.e. push the ball back out the way it came.
  if (Math.abs(ball.vx) > Math.abs(ball.vy)) return ball.vx > 0 ? 'left' : 'right';
  return ball.vy > 0 ? 'top' : 'bottom';
}

// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls, the paddle and the bricks. Bricks are killed and scored here too
// (the render loop only draws). Returns `true` if the ball is lost (exits
// through the bottom).
export function step(state, dt) {
  const { ball, paddle, bricks } = state;
  const totalMove = Math.hypot(ball.vx, ball.vy) * dt;
  const substeps = Math.max(1, Math.ceil(totalMove / SUBSTEP_DIST));
  const subDt = dt / substeps;
  let lost = false;

  for (let i = 0; i < substeps && !lost; i++) {
    const prevX = ball.x;
    const prevY = ball.y;
    ball.x += ball.vx * subDt;
    ball.y += ball.vy * subDt;

    // Side walls
    if (ball.x - ball.r < 0) {
      ball.x = ball.r;
      ball.vx = Math.abs(ball.vx);
    } else if (ball.x + ball.r > WIDTH) {
      ball.x = WIDTH - ball.r;
      ball.vx = -Math.abs(ball.vx);
    }

    // Ceiling
    if (ball.y - ball.r < 0) {
      ball.y = ball.r;
      ball.vy = Math.abs(ball.vy);
    }

    // Paddle: the whole ball box counts (a corner graze must still bounce),
    // and the rebound keeps the level speed with a minimum horizontal
    // component so a dead-center hit cannot stall the game.
    if (ball.vy > 0 && collides(ball, paddle)) {
      ball.y = paddle.y - ball.r;
      const speed = ballSpeed(state.level);
      const hit = Math.max(-1, Math.min(1, (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2)));
      let vx = speed * 0.6 * hit;
      const minVx = speed * PADDLE_MIN_VX_FACTOR;
      if (Math.abs(vx) < minVx) vx = (vx === 0 ? 1 : Math.sign(vx)) * minVx;
      ball.vx = vx;
      ball.vy = -Math.sqrt(Math.max(0, speed * speed - vx * vx));
      state.combo = 0; // touching the paddle resets the combo
    }

    // Bricks: resolve every live brick the ball overlaps — at most one flip
    // per axis per substep (a seam between two bricks must not cancel the
    // bounce) — and reposition the ball flush to the face that was hit.
    let flippedX = false;
    let flippedY = false;
    for (const brick of bricks) {
      if (!brick.alive || !collides(ball, brick)) continue;
      const face = hitFace(prevX, prevY, ball, brick);
      if (face === 'corner') {
        if (!flippedX) {
          ball.vx = -ball.vx;
          flippedX = true;
        }
        if (!flippedY) {
          ball.vy = -ball.vy;
          flippedY = true;
        }
        ball.x = ball.vx < 0 ? brick.x - ball.r : brick.x + brick.w + ball.r;
        ball.y = ball.vy < 0 ? brick.y - ball.r : brick.y + brick.h + ball.r;
      } else if (face === 'top') {
        if (!flippedY) {
          ball.vy = -ball.vy;
          flippedY = true;
        }
        ball.y = brick.y - ball.r;
      } else if (face === 'bottom') {
        if (!flippedY) {
          ball.vy = -ball.vy;
          flippedY = true;
        }
        ball.y = brick.y + brick.h + ball.r;
      } else if (face === 'left') {
        if (!flippedX) {
          ball.vx = -ball.vx;
          flippedX = true;
        }
        ball.x = brick.x - ball.r;
      } else {
        if (!flippedX) {
          ball.vx = -ball.vx;
          flippedX = true;
        }
        ball.x = brick.x + brick.w + ball.r;
      }
      brick.alive = false;
      state.combo += 1;
      state.score += scoreForBrick(brick, state.combo);
    }

    // Exit through the bottom: ball lost
    if (ball.y - ball.r > HEIGHT) {
      lost = true;
    }
  }
  return lost;
}

